/// Negate a double-double.
#[inline]
fn neg(v: DoubleDouble) -> DoubleDouble {
    DoubleDouble {
        high: -v.high,
        low: -v.low,
    }
}

/// Payne–Hanek argument reduction for `|x| ≥ 2²⁰`.
///
/// Returns `(q, r)` with `q` the quadrant (low bits of `round(x·2/π)`) and `r ∈
/// [-π/4, π/4]` a double-double.  Multiplies the 53-bit significand by a 256-bit
/// window of 2/π selected by the exponent, reads off the integer part (for `q`)
/// and a 128-bit signed fraction, and scales the fraction by π/2.
#[inline]
fn payne_hanek(x: f64) -> (i64, DoubleDouble) {
    let bits = x.to_bits();
    let e = ((bits >> super::EXP_SHIFT) & 0x7ff) as i64; // biased exponent
    let sig = u128::from((bits & 0x000F_FFFF_FFFF_FFFF) | 0x0010_0000_0000_0000);

    // x = sig · 2ᵐ with m = e − 1023 − 52.  The 2/π bit aligning to 2⁰ of x·2/π is
    // index k = m; pick the 256-bit window starting two bits above that.
    let m = e - 1075;
    let w0 = (((m - 2).max(0)) / 64) as usize;

    let word = |i: usize| u128::from(*FRAC_2_PI.get(w0 + i).unwrap_or(&0));
    let (wa, wb, wc, wd) = (word(0), word(1), word(2), word(3));

    // P = sig · (wa·2¹⁹² + wb·2¹²⁸ + wc·2⁶⁴ + wd), as five 64-bit limbs.
    let (pa, pb, pc, pd) = (sig * wa, sig * wb, sig * wc, sig * wd);
    const MASK: u128 = 0xFFFF_FFFF_FFFF_FFFF;
    let p0 = pd as u64;
    let c = (pd >> 64) + (pc & MASK);
    let p1 = c as u64;
    let c = (c >> 64) + (pc >> 64) + (pb & MASK);
    let p2 = c as u64;
    let c = (c >> 64) + (pb >> 64) + (pa & MASK);
    let p3 = c as u64;
    let p4 = ((c >> 64) + (pa >> 64)) as u64;
    let p = [p0, p1, p2, p3, p4];

    // Units bit of x·2/π is at P bit `b = 256 + 64·w0 − m`.
    let b = 256 + 64 * w0 as i64 - m;
    let bit_at = |start: i64| -> u64 {
        let w = (start / 64) as usize;
        let o = (start % 64) as u32;
        let lo = p.get(w).copied().unwrap_or(0);
        let hi = p.get(w + 1).copied().unwrap_or(0);
        if o == 0 {
            lo
        } else {
            (lo >> o) | (hi << (64 - o))
        }
    };

    // 192-bit window [b−128, b+63]: top 64 bits are the integer part (quadrant),
    // low 128 bits are the signed fraction of x·2/π.
    let frac = (u128::from(bit_at(b - 64)) << 64) | u128::from(bit_at(b - 128));
    let q = bit_at(b) as i64;
    let frac = frac as i128;

    // round-to-nearest: a negative signed fraction means the integer rounded up.
    let quadrant = q.wrapping_sub((frac >> 127) as i64);

    // r = (frac / 2¹²⁸) · π/2 ∈ [-π/4, π/4], as a double-double.  Split the
    // 128-bit signed `frac` into two limbs (`frac = h·2⁶⁴ + l` in two's
    // complement) and convert with native `i64`/`u64` → `f64`: a direct
    // `frac as f64` (and the residual's `as i128`) lowers to the slow
    // `__floattidf`/`__fixdfti` compiler-rt libcalls.  `hf` carries the top
    // ≈53 bits; `lf` folds `h`'s lost low bits and `l` into the next ≈53, so the
    // pair keeps the same ≈2⁻¹⁰⁶ precision the i128 casts gave.
    let h = (frac >> 64) as i64;
    let l = frac as u64;
    let hf = h as f64;
    let hr = h.wrapping_sub(hf as i64);
    let lf = crate::fma(hr as f64, crate::exp2i(64), l as f64);
    let r = DoubleDouble {
        high: hf * crate::exp2i(-64),
        low: lf * crate::exp2i(-128),
    } * PIO2;

    (quadrant, r)
}

/// Payne–Hanek argument reduction to a 128-bit `Dint` reduced angle — the
/// accurate-path counterpart of [`payne_hanek`], called only on the Ziv
/// fallback (any finite `x ≥ 2⁻²⁷`, so it subsumes the medium Cody–Waite range
/// too).
///
/// Returns `(quadrant, r)` with `r ∈ [−π/4, π/4]` a `Dint`.  Unlike the
/// double-double path, the residual fraction of `x·2/π` is read out **normalized**
/// — a 128-bit window taken at its own leading bit — so it keeps full 128-bit
/// relative precision even when `x` lies very close to a multiple of `π/2` and the
/// residual is tiny (the leading zeros the dd path absorbs into its 53-bit `hi`).
/// A 5-word (320-bit) window of 2/π and a 256-bit fraction extraction give ample
/// headroom over the ≈61-bit worst-case cancellation.
#[inline]
fn payne_hanek_dint(x: f64) -> (i64, Dint) {
    let bits = x.to_bits();
    let e = ((bits >> super::EXP_SHIFT) & 0x7ff) as i64;
    let sig = u128::from((bits & 0x000F_FFFF_FFFF_FFFF) | 0x0010_0000_0000_0000);

    let m = e - 1075;
    let w0 = (((m - 2).max(0)) / 64) as usize;
    let word = |i: usize| u128::from(*FRAC_2_PI.get(w0 + i).unwrap_or(&0));
    let (wa, wb, wc, wd, we) = (word(0), word(1), word(2), word(3), word(4));

    // P = sig · (wa·2²⁵⁶ + wb·2¹⁹² + wc·2¹²⁸ + wd·2⁶⁴ + we), as six 64-bit limbs.
    let (pa, pb, pc, pd, pe) = (sig * wa, sig * wb, sig * wc, sig * wd, sig * we);
    const MASK: u128 = 0xFFFF_FFFF_FFFF_FFFF;
    let p0 = pe as u64;
    let c = (pe >> 64) + (pd & MASK);
    let p1 = c as u64;
    let c = (c >> 64) + (pd >> 64) + (pc & MASK);
    let p2 = c as u64;
    let c = (c >> 64) + (pc >> 64) + (pb & MASK);
    let p3 = c as u64;
    let c = (c >> 64) + (pb >> 64) + (pa & MASK);
    let p4 = c as u64;
    let p5 = ((c >> 64) + (pa >> 64)) as u64;
    let p = [p0, p1, p2, p3, p4, p5];

    // Units bit of x·2/π is at P bit `b = 320 + 64·w0 − m`.
    let b = 320 + 64 * w0 as i64 - m;

    // Bits [start, start+63] of the zero-extended P (any signed `start`).
    let safe_word = |start: i64| -> u64 {
        let idx = start.div_euclid(64);
        let off = start.rem_euclid(64) as u32;
        let get = |i: i64| -> u64 {
            if i < 0 {
                0
            } else {
                p.get(i as usize).copied().unwrap_or(0)
            }
        };
        let lo = get(idx);
        if off == 0 {
            lo
        } else {
            (lo >> off) | (get(idx + 1) << (64 - off))
        }
    };

    // 256-bit signed fraction window [b−256, b−1]; its top bit (b−1) is the 2⁻¹
    // place, so the window read as a two's-complement integer is `resid · 2²⁵⁶`.
    let hi = (u128::from(safe_word(b - 64)) << 64) | u128::from(safe_word(b - 128));
    let lo = (u128::from(safe_word(b - 192)) << 64) | u128::from(safe_word(b - 256));

    // Sign of the residual; a negative residual means the integer rounded up.
    let sgn = hi >> 127 == 1;
    let quadrant = (safe_word(b) as i64).wrapping_add(i64::from(sgn));

    // |resid| · 2²⁵⁶ as an unsigned 256-bit pair.
    let (mag_hi, mag_lo) = if sgn {
        let (nlo, carry) = (!lo).overflowing_add(1);
        ((!hi).wrapping_add(u128::from(carry)), nlo)
    } else {
        (hi, lo)
    };

    // Normalize to a 128-bit significand: shift the leading set bit to bit 255,
    // keep the top 128 bits.  `value = mag/2²⁵⁶ = m/2^(128+lz)`, so `ex = −1 − lz`.
    let lz = if mag_hi != 0 {
        mag_hi.leading_zeros()
    } else {
        128 + mag_lo.leading_zeros()
    };
    let m128 = if lz == 0 {
        mag_hi
    } else if lz < 128 {
        (mag_hi << lz) | (mag_lo >> (128 - lz))
    } else {
        mag_lo << (lz - 128)
    };

    let frac = Dint {
        sgn,
        ex: -1 - i64::from(lz),
        m: m128,
    };
    (quadrant, frac.mul(&PIO2_DINT))
}

/// Negate a `Dint`.
#[inline]
const fn neg_dint(v: Dint) -> Dint {
    Dint { sgn: !v.sgn, ..v }
}

/// Horner evaluation of a `Dint` polynomial in `u`, low-degree first.
#[inline]
fn poly_dint(u: &Dint, coeffs: &[Dint]) -> Dint {
    let mut acc = coeffs[coeffs.len() - 1];
    for c in coeffs[..coeffs.len() - 1].iter().rev() {
        acc = c.add(&u.mul(&acc));
    }
    acc
}

/// `(sin(r), cos(r))` for `r ∈ [−π/4, π/4]` as `Dint`s — the accurate kernel.
#[inline]
fn sin_cos_dint(r: &Dint) -> (Dint, Dint) {
    let u = r.mul(r);
    (r.mul(&poly_dint(&u, &SIN_DINT)), poly_dint(&u, &COS_DINT))
}

/// `sin(r)` for `r ∈ [−π/4, π/4]` as a `Dint`.
#[inline]
fn sin_dint(r: &Dint) -> Dint {
    let u = r.mul(r);
    r.mul(&poly_dint(&u, &SIN_DINT))
}

/// `cos(r)` for `r ∈ [−π/4, π/4]` as a `Dint`.
#[inline]
fn cos_dint(r: &Dint) -> Dint {
    let u = r.mul(r);
    poly_dint(&u, &COS_DINT)
}

/// `1 / c` as a `Dint`, two Newton steps `y·(2 − c·y)` from the `f64` seed
/// `1/c`.  `c = cos(|x|)` is well away from a catastrophic seed (`|c| ≥ ≈2⁻⁶¹`),
/// so two steps reach the `Dint` arithmetic floor — the divide behind accurate
/// `tan`.
#[inline]
fn recip_dint(c: &Dint) -> Dint {
    let mut y = Dint::from_f64(1.0 / c.to_f64());
    for _ in 0..2 {
        y = y.mul(&TWO_DINT.add(&neg_dint(c.mul(&y))));
    }
    y
}

/// Reconstruct `sin(|x|)` (`Dint`) from the kernel pair and quadrant `q`.
#[inline]
const fn select_sin_dint(q: i64, s: Dint, c: Dint) -> Dint {
    let v = if q & 1 == 0 { s } else { c };
    if q & 2 == 0 { v } else { neg_dint(v) }
}

/// Reconstruct `cos(|x|)` (`Dint`) from the kernel pair and quadrant `q`.
#[inline]
const fn select_cos_dint(q: i64, s: Dint, c: Dint) -> Dint {
    let v = if q & 1 == 0 { c } else { s };
    if q.wrapping_add(1) & 2 == 0 {
        v
    } else {
        neg_dint(v)
    }
}

/// Argument reduction: `x ≥ 0` finite → `(quadrant, r)` with `r ∈ [-π/4, π/4]`.
#[inline]
fn rem_pio2(x: f64) -> (i64, DoubleDouble) {
    // Medium range: Cody–Waite with the 4-word π/2 (q small enough that
    // q·PIO2_1..PIO2_4 are exact).  Handles `q = 0` (no reduction) too.
    if x < 1_048_576.0 {
        let q = (x * FRAC_2_PI_F64).round_ties_even();
        // Subtract `q·π/2` word by word.  Each `q·PIO2_k` (k ≤ 4) is exact
        // (cleared low bits, |q| < 2²¹), so the three 2Sums capture every
        // residual of the first three words exactly; the fourth word folds into
        // the accumulated low part and the tail beyond PIO2_4 (≈2⁻¹²² after the
        // `q` scale) is dropped.  This flat fold — versus renormalizing the pair
        // after each word — keeps `r` accurate to ≈2⁻¹³⁰, so the relative Ziv
        // gate stays sound for any |r| ≳ 2⁻⁷⁰, far below the medium range's
        // worst-case cancellation; tinier residuals fall through to the
        // `payne_hanek_dint` accurate path.
        let a = DoubleDouble::from_sum(x, q * -PIO2_1);
        let b = DoubleDouble::from_sum(a.high, q * -PIO2_2);
        let c = DoubleDouble::from_sum(b.high, q * -PIO2_3);
        let lo = crate::fma(-q, PIO2_4, a.low + b.low + c.low);
        // SAFETY: |q| < 2²⁰.
        return (unsafe { q.to_int_unchecked() }, fast_sum(c.high, lo));
    }

    payne_hanek(x)
}

/// `sin(r)` for `r ∈ [-π/4, π/4]` as a double-double, by full double-double
/// Horner of [`SIN_KERNEL`] (≈2⁻¹²⁷) — the accurate `sin` half.
#[inline]
fn sin_kernel(r: DoubleDouble) -> DoubleDouble {
    r * poly_dd(r * r, &SIN_KERNEL)
}

/// `cos(r)` for `r ∈ [-π/4, π/4]` as a double-double, by full double-double
/// Horner of [`COS_KERNEL`] (≈2⁻¹²²) — the accurate `cos` half.
#[inline]
fn cos_kernel(r: DoubleDouble) -> DoubleDouble {
    poly_dd(r * r, &COS_KERNEL)
}

/// The squares shared by the fast sin/cos parts: `uu = r²`, `u2 = uu²`, and
/// `u3 = uu.high³`.
#[inline]
fn fast_squares(r: DoubleDouble) -> (DoubleDouble, DoubleDouble, f64) {
    let uu = r * r;
    let u = uu.high;
    (uu, uu * uu, u * u * u)
}

/// `sin(r)` from the precomputed squares — the `sin` half of the fast path.
///
/// Peels the three exact leading terms of `sin(r)/r` into double-double and
/// evaluates only the tiny `u³` tail ([`SIN_TAIL`]) in plain `f64`, so the result
/// comes out to ≈2⁻⁶⁰ for a fraction of [`sin_kernel`]'s cost.
#[inline]
fn sin_part_fast(r: DoubleDouble, uu: DoubleDouble, u2: DoubleDouble, u3: f64) -> DoubleDouble {
    // sin(r)/r = 1 − u/6 + u²/120 + u³·SIN_TAIL(u); every addend stays under
    // half its lead at the octant edge (`fold_ordering` below), so the folds
    // are ordered Fast2Sums, and `−u/6` is a multiply by the double-double
    // constant rather than `Div<f64>`'s two serial divisions.
    let sin_lead = ONE
        .add_ordered(uu * NEG_FRAC_1_6)
        .add_ordered(u2 * FRAC_1_120);
    let sin_over_r = sin_lead.add_ordered(DoubleDouble {
        high: u3 * crate::poly(uu.high, &SIN_TAIL),
        low: 0.0,
    });
    r * sin_over_r
}

/// `cos(r)` from the precomputed squares — the `cos` half of the fast path.  See
/// [`sin_part_fast`]; the `u³` tail is [`COS_TAIL`].
#[inline]
fn cos_part_fast(uu: DoubleDouble, u2: DoubleDouble, u3: f64) -> DoubleDouble {
    // cos(r) = 1 − u/2 + u²/24 + u³·COS_TAIL(u); ordered Fast2Sum folds as in
    // [`sin_part_fast`] (`|u/2| ≤ 0.309` is the tightest — see `fold_ordering`).
    let cos_lead = ONE.add_ordered(uu * -0.5).add_ordered(u2 * FRAC_1_24);
    cos_lead.add_ordered(DoubleDouble {
        high: u3 * crate::poly(uu.high, &COS_TAIL),
        low: 0.0,
    })
}

/// `sin(r)` for `r ∈ [-π/4, π/4]`, the fast path — only the `sin` half.
#[inline]
fn sin_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let (uu, u2, u3) = fast_squares(r);
    sin_part_fast(r, uu, u2, u3)
}

/// `cos(r)` for `r ∈ [-π/4, π/4]`, the fast path — only the `cos` half.
#[inline]
fn cos_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let (uu, u2, u3) = fast_squares(r);
    cos_part_fast(uu, u2, u3)
}

/// Lean fast kernel computing both halves, for `sincos`.
#[inline]
fn sin_cos_kernel_fast(r: DoubleDouble) -> (DoubleDouble, DoubleDouble) {
    let (uu, u2, u3) = fast_squares(r);
    (sin_part_fast(r, uu, u2, u3), cos_part_fast(uu, u2, u3))
}

/// `tan(r)` for `r ∈ [−π/4, π/4]`, as a double-double, via the direct series
/// `tan(r) = r·T(r²)`.  The 6 leading terms of `T` are carried in double-double
/// ([`TAN_LEADS`], 2-way Estrin) and the `v⁶` remainder ([`TAN_TAIL`]) in plain
/// `f64`.  One kernel — versus the sin/cos pair plus a reciprocal — feeds [`tan`].
///
/// Every fold uses [`DoubleDouble::add_ordered`]: `tan`'s series coefficients
/// decay fast enough that each addend stays under half its lead even at
/// `v = (π/4)²` (asserted in `fold_ordering` below).
#[inline]
fn tan_kernel_fast(r: DoubleDouble) -> DoubleDouble {
    let w = r * r; // v = r²
    let v = w.high;
    let v2 = v * v;
    let v6 = v2 * v2 * v2;
    let w2 = w * w;
    let p0 = TAN_LEADS[0].add_ordered(w * TAN_LEADS[1]);
    let p1 = TAN_LEADS[2].add_ordered(w * TAN_LEADS[3]);
    let p2 = TAN_LEADS[4].add_ordered(w * TAN_LEADS[5]);
    let t = p0
        .add_ordered(w2 * p1.add_ordered(w2 * p2))
        .add_ordered(DoubleDouble {
            high: v6 * crate::poly(v, &TAN_TAIL),
            low: 0.0,
        });
    r * t
}

/// Reconstruct `sin(|x|)` from the kernel pair and quadrant `q` (before the sign
/// of `x` is restored).  Shared by the fast and accurate paths so they select
/// identically.
#[inline]
fn select_sin(q: i64, s: DoubleDouble, c: DoubleDouble) -> DoubleDouble {
    let v = if q & 1 == 0 { s } else { c };
    if q & 2 == 0 { v } else { neg(v) }
}

/// Reconstruct `cos(|x|)` from the kernel pair and quadrant `q`.
#[inline]
fn select_cos(q: i64, s: DoubleDouble, c: DoubleDouble) -> DoubleDouble {
    let v = if q & 1 == 0 { c } else { s };
    if q.wrapping_add(1) & 2 == 0 {
        v
    } else {
        neg(v)
    }
}

/// Ziv gate: round `v` to `f64` when both ends of its `±TRIG_ZIV_EPS` (relative)
/// error interval agree, else `None` to fall back to the accurate kernel.
#[inline]
fn ziv(v: DoubleDouble) -> Option<f64> {
    let eps = v.high.abs() * TRIG_ZIV_EPS;
    let lo = v.high + (v.low - eps);
    let hi = v.high + (v.low + eps);
    (lo == hi).then_some(lo)
}

