/// Taylor coefficients of `(cos(πd/128) − 1)/d² = C1 + d²(C2 + d²·C3)` in the grid
/// unit `d = 128·a − round(128·a) ∈ [−½, ½]` (`Cₖ = (−1)ᵏ(π/128)^{2k}/(2k)!`); the
/// leading `C1` is double-double, the rest `f64`.  Residual angle `|πd/128| ≤
/// π/256`, so the dropped `d⁸` term is ≈2⁻⁶⁶.  See [`abs_sinpi_dd_lean`].
const SINPI_C1: DoubleDouble = DoubleDouble {
    high: -0.0003011964233730883,
    low: -1.9120164516417576e-20,
};
const SINPI_C2: f64 = 1.5119880908790113e-8;
const SINPI_C3: f64 = -3.036036034369748e-13;

/// Taylor coefficients of `sin(πd/128)/d = S0 + d²(S1 + d²(S2 + d²·S3))`
/// (`Sₖ = (−1)ᵏ(π/128)^{2k+1}/(2k+1)!`); `S0`, `S1` double-double, the rest `f64`.
/// See [`SINPI_C1`].
const SINPI_S0: DoubleDouble = DoubleDouble {
    high: 0.02454369260617026,
    low: 9.567553118338697e-19,
};
const SINPI_S1: DoubleDouble = DoubleDouble {
    high: -2.4641574764489986e-6,
    low: 1.0807811177153324e-22,
};
const SINPI_S2: f64 = 7.421954185344935e-11;
const SINPI_S3: f64 = -1.064507645268961e-15;

/// `sin(πx)` as a double-double for `|x| < 2⁵²`, where `x − q/2` is exact — the
/// accurate ≈2⁻¹²² kernel for the `lgamma` middle Ziv tier ([`abs_sinpi_dd`]).
///
/// Reduces `x = q/2 + r`, `r ∈ [−¼, ¼]`, and selects `±sin(πr)`/`±cos(πr)` by
/// `q mod 4`, with `πr ∈ [−π/4, π/4]` carried as a double-double into the full
/// double-double [`sin_kernel`]/[`cos_kernel`] (the middle tier needs their
/// ≈2⁻¹²² for its ≈2⁻⁹³ gate; the reflection *fast* leg takes the leaner
/// table-driven [`abs_sinpi_dd_lean`] instead).
#[inline]
fn sinpi_dd(x: f64) -> DoubleDouble {
    let q = (2.0 * x).round_ties_even();
    let theta = PI_DD * (x - q * 0.5);
    // SAFETY: `|x| < 2⁵²`, so `|q| < 2⁵³` fits an `i64`.
    match unsafe { q.to_int_unchecked::<i64>() } & 3 {
        0 => sin_kernel(theta),
        1 => cos_kernel(theta),
        2 => neg(sin_kernel(theta)),
        _ => neg(cos_kernel(theta)),
    }
}

/// `|sin(πx)|` as a double-double for `|x| < 2⁵²`, accurate ≈2⁻¹²² (see
/// [`sinpi_dd`]) — for the `lgamma` middle Ziv tier.
///
/// The lgamma reflection needs `ln|sin(πz)|` accurate even as `z` nears an
/// integer; there `|sin(πz)| ≈ π·|r|` with `r = z − round(z)` exact, so the
/// kernel's leading term keeps full relative accuracy.
#[inline]
pub(super) fn abs_sinpi_dd(x: f64) -> DoubleDouble {
    let v = sinpi_dd(x);
    if v.high < 0.0 { neg(v) } else { v }
}

/// `|sin(πx)|` as a double-double for `|x| < 2⁵²`, the lean table-driven kernel
/// (≈2⁻⁶⁶) — for the `lgamma` reflection *fast* leg, whose ≈2⁻⁶²–2⁻⁶⁶ gate has
/// ample room for it (the middle tier still uses the accurate [`abs_sinpi_dd`]).
///
/// Mirrors CORE-MATH's `as_sinpipid`.  `|sin(πx)| = sin(π·a)` with the period-1
/// even reduction `a = |x − round(x)| ∈ [0, ½]`; then `a = (k + d)/128` against the
/// [`SINPI_TABLE`] grid (`k = round(128·a)`, `d ∈ [−½, ½]`), and angle addition
///
/// `sin(π(k+d)/128) = sin(πk/128)·cos(πd/128) + cos(πk/128)·sin(πd/128)`
///
/// folds the tiny residual angle `πd/128 ∈ [−π/256, π/256]` through the short
/// [`SINPI_S0`]/[`SINPI_C1`] polynomials — far cheaper than a full-octant kernel.
/// Factoring `d` back out last keeps the leading `sin(π·a) ≈ π·a` exact as `a → 0`
/// (the near-integer case the gate cares about).  The result is non-negative
/// (`a ∈ [0, ½] ⇒ π·a ∈ [0, π/2]`), so no sign fixup.
#[inline]
pub(super) fn abs_sinpi_dd_lean(x: f64) -> DoubleDouble {
    let a = (x - x.round_ties_even()).abs();
    let s = a * 128.0;
    let kf = s.round_ties_even();
    let d = s - kf;
    // SAFETY: a ∈ [0, ½] ⇒ s ∈ [0, 64] ⇒ k ∈ 0..=64.
    let k = unsafe { kf.to_int_unchecked::<usize>() };
    let sg = SINPI_TABLE[k]; // sin(πk/128)
    let cg = SINPI_TABLE[64 - k]; // cos(πk/128) = sin(π(64−k)/128)

    let d2 = d * d;
    // sin(πd/128)/d = S0 + d²(S1 + d²(S2 + d²·S3))  (leading word double-double)
    let sin_over_d = SINPI_S0.add_ordered(DoubleDouble {
        high: d2 * crate::poly(d2, &[SINPI_S1.high, SINPI_S2, SINPI_S3]),
        low: 0.0,
    });
    // (cos(πd/128) − 1)/d² = C1 + d²(C2 + d²·C3)
    let cosm1_over_d2 = SINPI_C1.add_ordered(DoubleDouble {
        high: d2 * crate::poly(d2, &[SINPI_C2, SINPI_C3]),
        low: 0.0,
    });
    // sin(π·a) = sg + d·(cg·[sin θ/d] + sg·d·[(cos θ − 1)/d²]),  θ = πd/128.
    let bracket = cg * sin_over_d + sg * (cosm1_over_d2 * d);
    sg + bracket * d
}

/// Sine
#[must_use]
#[inline]
pub fn sin(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: sin(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // sin(|x|): even quadrants use sin(r), odd use cos(r); q&2 sets the sign.
    // Only the selected half is computed (vs. both for `sincos`).
    let need_cos = q & 1 != 0;
    let negate = q & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_cos {
        cos_kernel_fast(r)
    } else {
        sin_kernel_fast(r)
    });
    let magnitude = ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: re-reduce to a 128-bit `r` and round once.
        let (q, r) = payne_hanek_dint(x.abs());
        let v = if q & 1 != 0 {
            cos_dint(&r)
        } else {
            sin_dint(&r)
        };
        let v = if q & 2 != 0 { neg_dint(v) } else { v };
        v.to_f64()
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}

/// Cosine
#[must_use]
#[inline]
pub fn cos(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: cos(x) = 1 to within ½ ulp.
    if x.abs() < SMALL {
        return 1.0;
    }

    let (q, r) = rem_pio2(x.abs());

    // cos(|x|): even quadrants use cos(r), odd use sin(r); (q+1)&2 sets the sign.
    let need_sin = q & 1 != 0;
    let negate = q.wrapping_add(1) & 2 != 0;
    let signed = |v: DoubleDouble| if negate { neg(v) } else { v };

    let fast = signed(if need_sin {
        sin_kernel_fast(r)
    } else {
        cos_kernel_fast(r)
    });
    ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: re-reduce to a 128-bit `r` and round once.
        let (q, r) = payne_hanek_dint(x.abs());
        let v = if q & 1 != 0 {
            sin_dint(&r)
        } else {
            cos_dint(&r)
        };
        let v = if q.wrapping_add(1) & 2 != 0 {
            neg_dint(v)
        } else {
            v
        };
        v.to_f64()
    })
}

/// Simultaneous sine and cosine
#[must_use]
#[inline]
pub fn sincos(x: f64) -> (f64, f64) {
    if !x.is_finite() {
        return (f64::NAN, f64::NAN);
    }

    // |x| < 2⁻²⁷: (sin, cos) = (x, 1) to within ½ ulp; preserves ±0 in sin.
    if x.abs() < SMALL {
        return (x, 1.0);
    }

    let (q, r) = rem_pio2(x.abs());

    let (s, c) = sin_cos_kernel_fast(r);
    // Both components must pass the gate; otherwise recompute both accurately.
    let (sin, cos) = match (ziv(select_sin(q, s, c)), ziv(select_cos(q, s, c))) {
        (Some(sin), Some(cos)) => (sin, cos),
        _ => {
            // Accurate `Dint` path: re-reduce to a 128-bit `r` and round each once.
            let (q, r) = payne_hanek_dint(x.abs());
            let (s, c) = sin_cos_dint(&r);
            (
                select_sin_dint(q, s, c).to_f64(),
                select_cos_dint(q, s, c).to_f64(),
            )
        }
    };

    let sin = if x.is_sign_negative() { -sin } else { sin };
    (sin, cos)
}

/// Tangent
#[must_use]
#[inline]
pub fn tan(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }

    // |x| < 2⁻²⁷: tan(x) = x to within ½ ulp; preserves ±0.
    if x.abs() < SMALL {
        return x;
    }

    let (q, r) = rem_pio2(x.abs());

    // tan has period π, so tan(|x|) = tan(r) for even quadrants and −cot(r) =
    // −1/tan(r) for odd ones — one kernel, a reciprocal only half the time.
    let t = tan_kernel_fast(r);
    let fast = if q & 1 == 0 {
        t
    } else {
        // −1/t leanly: seed `y = −1/t.high` (the inner FMA's cancellation is
        // exact), fold `t.low` into the residual `e = 1 + y·t`, and take
        // `y·(1 + e)` — dropping `y·e²` ≈ 2⁻¹⁰⁴ relative, noise to the 2⁻⁵⁹
        // gate.  The full Newton `recip` (a double-double multiply, add, and
        // multiply on top of the divide) buys accuracy the gate cannot use.
        let y = -1.0 / t.high;
        let e = crate::fma(y, t.low, crate::fma(y, t.high, 1.0));
        DoubleDouble {
            high: y,
            low: y * e,
        }
    };
    let magnitude = ziv(fast).unwrap_or_else(|| {
        // Accurate `Dint` path: the sin/cos pair ratio in 128-bit fixed point.
        let (q, r) = payne_hanek_dint(x.abs());
        let (s, c) = sin_cos_dint(&r);
        let num = select_sin_dint(q, s, c);
        let den = select_cos_dint(q, s, c);
        num.mul(&recip_dint(&den)).to_f64()
    });

    if x.is_sign_negative() {
        -magnitude
    } else {
        magnitude
    }
}

/// The Fast2Sum-based folds of [`tan_kernel_fast`] need `|a| ≥ |b|`; prove the
/// orderings from coefficient-magnitude bounds at `v = w = (π/4)²`, the
/// octant's edge, with 2× margin (cf. the same-named module in `erf.rs`).
#[cfg(test)]
mod fold_ordering {
    use super::*;

    /// `sin_part_fast` / `cos_part_fast`: `1 ⊕ u·c₁ ⊕ u²·c₂ ⊕ u³·tail` with
    /// `u = r² ≤ (π/4)²`.
    #[test]
    fn sin_cos_leads() {
        let umax = core::f64::consts::FRAC_PI_4.powi(2) * 1.0001;
        let u2max = umax * umax;
        let u3max = umax.powi(3);
        let tail_mag = |tail: &[f64]| {
            tail.iter()
                .rev()
                .fold(0.0, |acc, c| crate::fast_mul_add(acc, umax, c.abs()))
        };

        for (c1, c2, tail) in [
            (
                NEG_FRAC_1_6.high.abs() + NEG_FRAC_1_6.low.abs(),
                FRAC_1_120.high + FRAC_1_120.low.abs(),
                &SIN_TAIL,
            ),
            (0.5, FRAC_1_24.high + FRAC_1_24.low.abs(), &COS_TAIL),
        ] {
            assert!(umax * c1 <= 0.5);
            let lead_min = 1.0 - umax * c1;
            assert!(u2max * c2 <= 0.5 * lead_min);
            let lead2_min = lead_min - u2max * c2;
            assert!(u3max * tail_mag(tail) <= 0.5 * lead2_min);
        }
    }

    /// The table-driven `abs_sinpi_dd_lean` folds the residual polynomials with
    /// `add_ordered` (`S0 ⊕ d²·(…)` and `C1 ⊕ d²·(…)`), which needs the leading
    /// coefficient to dominate the higher-order remainder.  `|d| ≤ ½`, so check
    /// the remainder stays under half the lead there.
    #[test]
    fn sinpi_table_leads() {
        let d2max = 0.25_f64; // (½)²
        let mag = |c: DoubleDouble| c.high.abs() + c.low.abs();
        let poly_mag = |c: &[f64]| {
            c.iter()
                .rev()
                .fold(0.0, |acc, c| crate::fast_mul_add(acc, d2max, c.abs()))
        };
        // sin: |S0| ≥ |d²·(S1 + d²(S2 + d²·S3))|
        assert!(d2max * poly_mag(&[SINPI_S1.high, SINPI_S2, SINPI_S3]) <= 0.5 * mag(SINPI_S0));
        // cos: |C1| ≥ |d²·(C2 + d²·C3)|
        assert!(d2max * poly_mag(&[SINPI_C2, SINPI_C3]) <= 0.5 * mag(SINPI_C1));
    }

    #[test]
    fn tan_leads() {
        // Slack for the rounding of r and w = r·r at the octant edge.
        let wmax = core::f64::consts::FRAC_PI_4.powi(2) * 1.0001;
        let mag = |c: DoubleDouble| c.high.abs() + c.low.abs();

        // p0/p1/p2 = L₂ₖ ⊕ w·L₂ₖ₊₁
        for pair in TAN_LEADS.chunks(2) {
            assert!(wmax * mag(pair[1]) <= 0.5 * pair[0].high.abs());
        }

        // inner = p1 ⊕ w²·p2, outer = p0 ⊕ w²·inner, t = outer ⊕ v⁶·tail
        let w2max = wmax * wmax;
        let p2_mag = mag(TAN_LEADS[4]) + wmax * mag(TAN_LEADS[5]);
        let p1_min = TAN_LEADS[2].high - wmax * mag(TAN_LEADS[3]);
        assert!(w2max * p2_mag <= 0.5 * p1_min);
        let inner_mag = mag(TAN_LEADS[2]) + wmax * mag(TAN_LEADS[3]) + w2max * p2_mag;
        let p0_min = TAN_LEADS[0].high - wmax * mag(TAN_LEADS[1]);
        assert!(w2max * inner_mag <= 0.5 * p0_min);
        let tail_mag = TAN_TAIL
            .iter()
            .rev()
            .fold(0.0, |acc, c| crate::fast_mul_add(acc, wmax, c.abs()));
        let outer_min = p0_min - w2max * inner_mag;
        assert!(wmax.powi(3) * tail_mag <= 0.5 * outer_min);
    }
}
